/// <summary>
/// designed from AVA
/// </summary>
class AVANumberSeqModuleForeignTrade     extends NumberSeqApplicationModule
{
}

Method.Source:
/// <summary>
/// This method is currently undocumented!
/// </summary>
protected void loadModule()
{
    NumberSeqDatatype datatype = NumberSeqDatatype::construct();
    datatype.parmDatatypeId(extendedtypenum(AVAListZ5ADispatchId));
    datatype.parmReferenceHelp(literalstr('@NDX:AVAZ5ADispatchHelp'));
    datatype.parmReferenceLabel(literalstr('@NDX:AVAZ5ADispatch'));
    datatype.parmWizardIsManual(NoYes::No);
    datatype.parmWizardIsChangeDownAllowed(NoYes::No);
    datatype.parmWizardIsChangeUpAllowed(NoYes::No);
    datatype.parmSortField(3);

    datatype.addParameterType(NumberSeqParameterType::DataArea, true, false);
    this.create(datatype);

    /*NumberSeqDatatype datatype = NumberSeqDatatype::construct();
    datatype.parmDatatypeId(extendedtypenum(AVAListZ4DispatchId));
    datatype.parmReferenceHelp(literalstr("@NDX:AVAListZ4DispatchIdNumberSeqHelp"));
    datatype.parmReferenceLabel(literalstr("@NDX:AVAListZ4DispatchId"));
    datatype.parmWizardIsManual(NoYes::No);
    datatype.parmWizardIsChangeDownAllowed(NoYes::No);
    datatype.parmWizardIsChangeUpAllowed(NoYes::No);
    datatype.parmSortField(3);

    datatype.addParameterType(NumberSeqParameterType::DataArea, true, false);
    this.create(datatype);*/
}

/// <summary>
/// numberSeqModule
/// </summary>
/// <returns>NumberSeqModule</returns>
public NumberSeqModule numberSeqModule()
{
    return NumberSeqModule::ForeignTrade;
}

/// <summary>
///  Appends the current class to the map that links modules to number sequence data type generators.
/// </summary>
/// <param name = "numberSeqModuleNamesMap">Map</param>
[SubscribesTo(classstr(NumberSeqGlobal),delegatestr(NumberSeqGlobal,buildModulesMapDelegate))]
static void buildModulesMapSubsciber(Map numberSeqModuleNamesMap)
{
    NumberSeqGlobal::addModuleToMap(classnum(AVANumberSeqModuleForeignTrade), numberSeqModuleNamesMap);
}
